// The dashboard's API client, generated by orval from the committed OpenAPI schema
// (openapi.json, written by tools/export_openapi.py; grill log Q12). Never edit src/generated by
// hand: change the API, export the schema, then `docker compose run --rm web npm run generate`.
// CI regenerates it and fails when the committed client differs.
import { defineConfig } from "orval";

/** One readable name per operation from its method and path, which OpenAPI keeps unique:
 *  GET /dashboard/loan -> getDashboardLoan, POST /alerts/{alert_id}/close ->
 *  postAlertsByAlertIdClose. */
function operationName(_operation: unknown, route: string, verb: string): string {
  const words = route
    .split("/")
    .filter((part) => part !== "")
    .flatMap((part) => {
      const parameter = /^\$?\{(.+)\}$/.exec(part);
      const name = parameter ? (parameter[1] ?? "") : part;
      return [...(parameter ? ["by"] : []), ...name.split(/[^A-Za-z0-9]+/)];
    })
    .filter((word) => word !== "");
  return verb + words.map((word) => word.charAt(0).toUpperCase() + word.slice(1)).join("");
}

export default defineConfig({
  cmbs: {
    input: { target: "./openapi.json" },
    output: {
      target: "./src/generated/api.ts",
      mode: "tags-split",
      client: "fetch",
      // Relative URLs: the page and the API share one origin (`cmbs serve`).
      baseUrl: "",
      formatter: "biome",
      override: {
        operationName,
        // Every call goes through src/http.ts, which sends the user and turns a refusal into an
        // Error with the server's words; a call resolves to the answer's body.
        mutator: { path: "./src/http.ts", name: "http" },
        fetch: { includeHttpResponseReturnType: false },
      },
    },
  },
});
